function solve(arr) {
  function valid(i, min, max) {
    if (i >= arr.length || arr[i] === null) return true;
    if (arr[i] <= min || arr[i] >= max) return false;
    return valid(2 * i + 1, min, arr[i]) && valid(2 * i + 2, arr[i], max);
  }
  return valid(0, -Infinity, Infinity);
}

function solve(arr) {
  const inorder = [];
  function dfs(i) {
    if (i >= arr.length || arr[i] === null) return;
    dfs(2 * i + 1);
    inorder.push(arr[i]);
    dfs(2 * i + 2);
  }
  dfs(0);
  for (let i = 1; i < inorder.length; i++) if (inorder[i] <= inorder[i-1]) return false;
  return true;
}

